import{_ as l,a0 as p,w as r,s as d,ao as o,I as a,x as n,a1 as e,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"使用 WinSCP 将文件和文件夹从 Windows 传输到 Linux | LCTT x X-CMD","titleTemplate":false,"description":"使用 WinSCP 将文件和文件夹从 Windows 传输到 Linux | LCTT (202211) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 WinSCP 将文件和文件夹从 Windows 传输到 Linux | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 WinSCP 将文件和文件夹从 Windows 传输到 Linux | LCTT (202211) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202211/20221101.1 ⭐️⭐️ Transfer files and folders from Windows to Linux with WinSCP","title":"使用 WinSCP 将文件和文件夹从 Windows 传输到 Linux","tag":"202211","desc":""},"relativePath":"202211/20221101.1 ⭐️⭐️ Transfer files and folders from Windows to Linux with WinSCP.md","filePath":"[post].md"}'),u={name:"202211/20221101.1 ⭐️⭐️ Transfer files and folders from Windows to Linux with WinSCP.md"};function f(g,s,h,m,w,x){const i=p("Link");return r(),d("div",null,[s[26]||(s[26]=o(`<h1 id="使用-winscp-将文件和文件夹从-windows-传输到-linux" tabindex="-1">使用 WinSCP 将文件和文件夹从 Windows 传输到 Linux <a class="header-anchor" href="#使用-winscp-将文件和文件夹从-windows-传输到-linux" aria-label="Permalink to “使用 WinSCP 将文件和文件夹从 Windows 传输到 Linux”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202211/28/092919hf6y9ojjlmmsfmlm.jpg" alt=""></p><blockquote><p>如果你正在寻找一种快速的从你的 Windows 计算机传输文件到你的 Linux 计算机的方法，那么开源的 WinSCP 实用程序会使其很容易地通过网络传输文件或文件夹。</p></blockquote><p>有时，你需要通过文件传输文件。有很多文件共享服务，但是大多数的共享服务都要求你发送你的文件到互联网上。当两台计算机并排在一起或在一栋建筑物中时，通过互联网传输文件，这似乎看起来绕了很远的路（更不用说隐私问题）。开源的 WinSCP 实用程序会使其很轻易地通过网络将一个文件或一个文件夹从你的 Windows 计算机传输到你的 Linux 计算机。</p><h3 id="ip-地址" tabindex="-1">IP 地址 <a class="header-anchor" href="#ip-地址" aria-label="Permalink to “IP 地址”">​</a></h3><p>在你可以传输之前，你必须知道目标计算机的 IP 地址或完全限定域名。假设它是一台在你的同一个网络上的计算机，并且你没有运行 DNS 服务器来解析计算机名称，你可以在 Linux 计算机上使用 <code>ip</code> 命令来找到目标 IP 地址：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linux]$ ip addr show |grep &#39;inet &#39;</span></span>
<span class="line"><span>inet 127.0.0.1/8 scope host lo  </span></span>
<span class="line"><span>inet 192.168.1.23/24 brd 10.0.1.255 scope global noprefixroute eth0</span></span></code></pre></div><p><code>127.0.0.1</code> 是一个 <ruby>环回地址<rt>loopback address</rt></ruby> ，计算机仅使用它来自我通信，因此在这个示例中，正确的地址是 <code>192.168.1.23</code> 。在你的系统中，IP 地址可能会看起来有所不同。如果你不确定哪个是哪个，你可以逐个尝试到你找到正确的 IP 地址 （然后，在一些地方写下来！）</p><p>或者，你可以查找你的路由器设置，它列出了所有通过 DHCP 分配的地址。</p><h3 id="防火墙和地址" tabindex="-1">防火墙和地址 <a class="header-anchor" href="#防火墙和地址" aria-label="Permalink to “防火墙和地址”">​</a></h3><p><code>WinSCP</code> 命令使用 OpenSSH 协议，因此，你的 Linux 计算机必需运行 OpenSSH 服务器软件，并且你的 Linux 计算机的防火墙必需允许 SSH 通信。</p><p>如果你不确定你的 Linux 机器是否在运行 SSH ，那么在 Linux 机器的终端上运行这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linux]$ sudo systemctl enable --now sshd</span></span></code></pre></div><p>为确保你的防火墙允许 SSH 通信，运行这个命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[linux]$ sudo firewall-cmd --add-servicessh--permanent</span></span></code></pre></div>`,15)),a("p",null,[s[1]||(s[1]=n("关于 Linux 上的防火墙的更多信息，阅读 ",-1)),e(i,{href:"https://opensource.com/article/19/7/make-linux-stronger-firewalls"},{default:t(()=>[...s[0]||(s[0]=[n("增强 Linux 防火墙",-1)])]),_:1}),s[2]||(s[2]=n(" 。",-1))]),s[27]||(s[27]=a("h3",{id:"使用-winscp",tabindex:"-1"},[n("使用 WinSCP "),a("a",{class:"header-anchor",href:"#使用-winscp","aria-label":"Permalink to “使用 WinSCP”"},"​")],-1)),a("p",null,[s[5]||(s[5]=n("WinSCP 是一款针对微软 Windows 的开源 SSH 文件传输应用程序。为使用它，你必须先 ",-1)),e(i,{href:"https://sourceforge.net/projects/winscp/files/"},{default:t(()=>[...s[3]||(s[3]=[n("下载",-1)])]),_:1}),s[6]||(s[6]=n(" 和 ",-1)),e(i,{href:"https://sourceforge.net/projects/winscp/files/"},{default:t(()=>[...s[4]||(s[4]=[n("安装",-1)])]),_:1}),s[7]||(s[7]=n(" 它。",-1))]),s[28]||(s[28]=o(`<p>在你安装完成后，打开 WinSCP ，并在 “<ruby>文件协议<rt>File Protocol</rt></ruby>” 字段中选择 “SCP” 选项。</p><p>在 “<ruby>主机名称<rt>Host name</rt></ruby>” 字段中添加你的 Linux 计算机的 IP 地址或 DNS 名称，并在 “<ruby>端口号<rt>Port number</rt></ruby>” 字段中输入 <strong>22</strong> 。针对该 Linux 计算机，输入你的用户名称和密码，然后单击 WinSCP 窗口底部的 “<ruby>登录<rt>Login</rt></ruby>” 按钮。</p><p><img src="https://opensource.com/sites/default/files/2022-10/winscp.loginwindow.png" alt="Image of the WinSCP login window."></p><p>验证你是否获取了登录 Linux 计算机的身份授权。在验证成功后，你的 Linux 计算机的 IP 地址或 DNS 名称将显示在窗口的顶部。</p><p><img src="https://opensource.com/sites/default/files/2022-10/WinSCPwindow.showing.IPinfo.png" alt="Image of a WinSCP window showing where IP adress is located."></p><p>现在，你可以从左侧的 Windows 面板中拖拽一个文件（如示例，我使用 <code>winscp-test.txt</code> 文件）到右侧的目标 Linux 计算机目标，接下来文件会传输。</p><p><img src="https://opensource.com/sites/default/files/2022-10/WinSCP.drapdropwindow.png" alt="Image of drag and drop window in WinSCP."></p><p>或者，你可以在左侧的面板中右键单击一个文件，然后上传它到右侧的远程目标的面板。</p><p><img src="https://opensource.com/sites/default/files/2022-10/RightclickUploadfileWInSCP.png" alt="Image of a right click option to upload files in WinSCP."></p><h3 id="验证副本" tabindex="-1">验证副本 <a class="header-anchor" href="#验证副本" aria-label="Permalink to “验证副本”">​</a></h3><p>打开一个 Linux 终端，然后使用 <code>ls</code> 命令来查看已传输的 <code>winscp-test.txt</code> 文件。在我的示例中，它出现在我的主目录， <code>/home/sysadmin</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls</span></span>
<span class="line"><span>Desktop</span></span>
<span class="line"><span>Documents</span></span>
<span class="line"><span>Downloads</span></span>
<span class="line"><span>Music</span></span>
<span class="line"><span>Pictures</span></span>
<span class="line"><span>pscp-test.txt[...]</span></span></code></pre></div><p>你已经通过网络成功地将一个文件从一台 Windows 计算机传输到一台 Linux 计算机！</p><p>当然，你也可以使用类似上述的技术，将文件和文件夹从一台 Linux 计算机传输到一台 Windows 计算机。</p><h3 id="远程复制" tabindex="-1">远程复制 <a class="header-anchor" href="#远程复制" aria-label="Permalink to “远程复制”">​</a></h3>`,15)),a("p",null,[s[9]||(s[9]=n("使用强大的开源 WinSCP 应用程序，你可以访问在你家中或工作场所的任意一台计算机、你拥有账户的服务器、甚至是移动设备、",-1)),e(i,{href:"https://www.redhat.com/en/topics/edge-computing/what-is-edge-computing?intcmp=7013a000002qLH8AAM"},{default:t(()=>[...s[8]||(s[8]=[n("边缘设备",-1)])]),_:1}),s[10]||(s[10]=n("、物联网设备。使用这个极好的工具来传输文件就像你在本地目录下将一个文件复制到另一个本地目录一样容易！",-1))]),s[29]||(s[29]=a("hr",null,null,-1)),a("p",null,[s[12]||(s[12]=n("via: ",-1)),e(i,{href:"https://opensource.com/article/22/11/transfer-files-folders-windows-linux-winscp"},{default:t(()=>[...s[11]||(s[11]=[n("https://opensource.com/article/22/11/transfer-files-folders-windows-linux-winscp",-1)])]),_:1})]),a("p",null,[s[17]||(s[17]=n("作者：",-1)),e(i,{href:"https://opensource.com/users/plaubscher"},{default:t(()=>[...s[13]||(s[13]=[n("Paul",-1)])]),_:1}),s[18]||(s[18]=n(" 选题：",-1)),e(i,{href:"https://github.com/lkxed"},{default:t(()=>[...s[14]||(s[14]=[n("lkxed",-1)])]),_:1}),s[19]||(s[19]=n(" 译者：",-1)),e(i,{href:"https://github.com/robsean"},{default:t(()=>[...s[15]||(s[15]=[n("robsean",-1)])]),_:1}),s[20]||(s[20]=n(" 校对：",-1)),e(i,{href:"https://github.com/wxy"},{default:t(()=>[...s[16]||(s[16]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[23]||(s[23]=n("本文由 ",-1)),e(i,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[n("LCTT",-1)])]),_:1}),s[24]||(s[24]=n(" 原创编译，",-1)),e(i,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[n("Linux中国",-1)])]),_:1}),s[25]||(s[25]=n(" 荣誉推出",-1))])])}const C=l(u,[["render",f]]);export{k as __pageData,C as default};
